"""Verify invsqrt 563d0583 (74,560.91 expected) with the unmodified official verifier.

CPU only. Nothing submitted. The circuit is embedded as base64 because Kaggle script
kernels upload only main.py.
"""
import base64
import hashlib
import os
import pathlib
import subprocess
import sys

B64 = """

"""
COMP = "google-verifiable-quantum-circuit-compilation"
EXPECT_SHA = "563d0583f736afc2d8111f376bc1bd5ce6aef686525b0dd281fc1f2b4eb09321"
EXPECT_COST = 74560.91


def find_comp():
    for p in (pathlib.Path("/kaggle/input/competitions") / COMP,
              pathlib.Path("/kaggle/input") / COMP):
        if (p / "verifiers").is_dir():
            return p
    for p in pathlib.Path("/kaggle/input").rglob("verify_submission_invsqrt.py"):
        return p.parent.parent.parent
    return None


def main():
    comp = find_comp()
    print("competition:", comp, flush=True)
    if comp is None:
        print("NO COMPETITION", flush=True)
        return
    raw = base64.b64decode("".join(B64.split()))
    sha = hashlib.sha256(raw).hexdigest()
    print("decoded bytes", len(raw), "sha256", sha, flush=True)
    assert sha == EXPECT_SHA, "sha mismatch"
    out = pathlib.Path("/tmp/invsqrt.kmb")
    out.write_bytes(raw)
    env = dict(os.environ, PYTHONPATH=f"{comp / 'kickmix'}:{comp / 'verifiers'}",
               JAX_PLATFORMS="cpu", OMP_NUM_THREADS="4")
    cmd = [sys.executable, str(comp / "verifiers/invsqrt/verify_submission_invsqrt.py"), str(out)]
    print("RUN", " ".join(cmd), flush=True)
    r = subprocess.run(cmd, capture_output=True, text=True, env=env, cwd=str(comp / "verifiers"))
    print("rc =", r.returncode, flush=True)
    print(r.stdout[-6000:], flush=True)
    print("--- stderr ---", flush=True)
    print(r.stderr[-2000:], flush=True)
    print("EXPECT cost", EXPECT_COST, " (ours 0af21cb8 = 74797.365357)", flush=True)
    print("DONE", flush=True)


main()
